// Supplied reference photos are embedded so no separate public assets are required.
const MENTOR_PAGE_PHOTOS = [{"src":"data:image/png;base64,","iw":1839,"ih":1035,"x":291,"y":88,"w":1527,"h":774,"alt":"Become a Mentor — introduction and trusted companies"},{"src":"data:image/png;base64,","iw":1836,"ih":1035,"x":289,"y":88,"w":1527,"h":527,"alt":"Top mentors"},{"src":"data:image/png;base64,","iw":1847,"ih":1034,"x":300,"y":88,"w":1527,"h":577,"alt":"Why should you be an Unstop Mentor?"},{"src":"data:image/png;base64,","iw":1842,"ih":1035,"x":295,"y":88,"w":1527,"h":625,"alt":"How can you be a Mentor? Four steps"},{"src":"data:image/png;base64,","iw":1839,"ih":1029,"x":291,"y":438,"w":1527,"h":572,"alt":"Mentorship video preview (static photo)"},{"src":"data:image/png;base64,","iw":1830,"ih":1041,"x":283,"y":94,"w":1527,"h":441,"alt":"Mentor testimonials"},{"src":"data:image/png;base64,","iw":1839,"ih":1038,"x":292,"y":92,"w":1527,"h":938,"alt":"Frequently asked questions and contact information"}];
function MentorPhotoPage({ sidebarRef, onClose }: { sidebarRef: React.RefObject<HTMLElement | null>; onClose: () => void }) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [left, setLeft] = useState(234);
  useLayoutEffect(() => {
    const previousFocus = document.activeElement as HTMLElement | null;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const update = () => setLeft(window.innerWidth < 1024 ? 6 : (sidebarRef.current?.getBoundingClientRect().right ?? 226) + 8);
    update();
    const observer = new ResizeObserver(update);
    if (sidebarRef.current) observer.observe(sidebarRef.current);
    window.addEventListener('resize', update);
    const keydown = (event: KeyboardEvent) => { if (event.key === 'Escape') { event.preventDefault(); onClose(); } };
    document.addEventListener('keydown', keydown);
    scrollRef.current?.focus();
    return () => { observer.disconnect(); window.removeEventListener('resize', update); document.removeEventListener('keydown', keydown); document.body.style.overflow = previousOverflow; previousFocus?.focus(); };
  }, [sidebarRef, onClose]);
  if (typeof document === 'undefined') return null;
  return createPortal(
    <section aria-label="Become a Mentor" className="mentor-photo-page" style={{left}}>
      <header className="mentor-photo-header">
        <button type="button" onClick={onClose} aria-label="Back to previous page">← Back</button>
        <span>Home <span aria-hidden="true"> / </span> Become a Mentor</span>
        <button type="button" onClick={onClose} aria-label="Close mentor page">✕</button>
      </header>
      <div ref={scrollRef} tabIndex={0} aria-label="Mentor page photos, scroll to see all sections" className="mentor-photo-scroll">
        {MENTOR_PAGE_PHOTOS.map((photo, index) => (
          <figure key={photo.alt} style={{position:'relative',width:'100%',aspectRatio:photo.w+'/'+photo.h,overflow:'hidden',margin:0}}>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={photo.src} alt={photo.alt} loading={index === 0 ? 'eager' : 'lazy'} draggable={false}
              style={{position:'absolute',maxWidth:'none',width:(photo.iw/photo.w*100)+'%',height:'auto',left:(-photo.x/photo.w*100)+'%',top:(-photo.y/photo.h*100)+'%'}} />
          </figure>
        ))}
        <div className="w-full min-w-0 shrink-0 mt-auto static">
          <Footer />
        </div>
      </div>
      <style>{`
        .mentor-photo-page{position:fixed;top:6px;right:6px;bottom:6px;z-index:45;display:flex;flex-direction:column;overflow:hidden;border-radius:18px;background:white;box-shadow:0 0 0 8px #e0efff;color:#1c3b5b;font-family:Arial,Helvetica,sans-serif}
        .mentor-photo-header{display:flex;align-items:center;gap:18px;min-height:64px;padding:12px 24px;border-bottom:1px solid #e2e2e2;background:#fff;flex-shrink:0;font-size:14px}
        .mentor-photo-header span{flex:1}.mentor-photo-header button{cursor:pointer;border:1px solid #d4e6fa;border-radius:999px;background:#f3f9ff;color:#0073e6;padding:8px 14px}
        .mentor-photo-scroll{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#99b6d5 #f2f7fc;scrollbar-gutter:stable}
        .mentor-photo-scroll::-webkit-scrollbar{width:9px}.mentor-photo-scroll::-webkit-scrollbar-thumb{background:#99b6d5;border-radius:9px}.mentor-photo-scroll::-webkit-scrollbar-track{background:#f2f7fc}
        .mentor-photo-page button:focus-visible,.mentor-photo-scroll:focus-visible{outline:2px solid #0073e6;outline-offset:-2px}
        @media(max-width:767px){.mentor-photo-scroll figure{min-width:760px}.mentor-photo-header{padding:10px;gap:10px;font-size:12px}}
      `}</style>
    </section>, document.body
  );
}


